xpath.script:
(function() {
    try {
        var savedTheme = localStorage.getItem('odoo_interface_theme') || 'midnight-gold';
        if (!savedTheme || savedTheme === 'classic') {
            savedTheme = 'midnight-gold';
            try { localStorage.setItem('odoo_interface_theme', 'midnight-gold'); } catch(err) {}
        }
        document.documentElement.setAttribute('data-theme', savedTheme);
    } catch (e) {}

    function debrandTitle() {
        if (document.title.indexOf("Odoo") !== -1) {
            document.title = document.title.replace(/Odoo/g, "Your Company");
        }
    }
    debrandTitle();
    var titleEl = document.querySelector('title');
    if (titleEl) {
        var observer = new MutationObserver(debrandTitle);
        observer.observe(titleEl, { childList: true, characterData: true, subtree: true });
    }
})();
